-- Additive private enrollment drafts. Paths are generated by the API and never returned;
-- patients receive only five-minute signed URLs through authenticated enrollment reads.
ALTER TABLE public.launch_cases ADD COLUMN "enrollmentDraft" jsonb;
ALTER TABLE public.launch_cases ADD CONSTRAINT launch_cases_enrollment_draft_object
  CHECK ("enrollmentDraft" IS NULL OR
    (jsonb_typeof("enrollmentDraft") = 'object' AND octet_length("enrollmentDraft"::text) <= 20000));
-- launch_cases already has RLS enabled and no client grants. Preserve that access model.
